#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

banner "Azure deployment bootstrap (spec 013): the steps only you can do"

REPO="ponatosik/diceus-claims-module"
RESOURCE_GROUP="rg-diceus-claims"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Azure: sign in and pick the subscription"
say "Everything is deployed into one resource group on your Pay-As-You-Go subscription."
open_url "https://portal.azure.com/#view/Microsoft_Azure_Billing/SubscriptionsBladeV2"
step "Sign in and check the subscription you want to use is listed and Active."
note "Budget: \$2/month. Every resource is on a free or capped tier (ADR-0012); a budget alert emails you."
pause "Press Enter when you're signed in and know which subscription to use."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Cloud Shell: create the deploy identity"
say "Cloud Shell has the Azure CLI built in. You'll paste one block there."
open_url "https://shell.azure.com/bash"
step "In Cloud Shell (Bash), if you have several subscriptions run: az account set --subscription \"<name or id>\""
note "The deploy identity gets Contributor, Key Vault Secrets Officer, and a role-assignment right limited to one role."
step "Then copy everything between the lines below and paste it into Cloud Shell:"
printf '\n%s──────────────── copy from here ────────────────%s\n' "$DIM" "$RESET"
cat <<'CLOUDSHELL'
set -e
SUBSCRIPTION_ID=$(az account show --query id -o tsv)
TENANT_ID=$(az account show --query tenantId -o tsv)
echo "Subscription offer: $(az rest --method get --url "https://management.azure.com/subscriptions/$SUBSCRIPTION_ID?api-version=2020-01-01" --query subscriptionPolicies.quotaId -o tsv)"
for ns in Microsoft.Web Microsoft.Sql Microsoft.Storage Microsoft.KeyVault Microsoft.Consumption; do az provider register --namespace "$ns" -o none; done
az group create --name rg-diceus-claims --location westeurope -o none
APP_ID=$(az ad app list --display-name gh-diceus-claims-deploy --query '[0].appId' -o tsv)
[ -n "$APP_ID" ] || APP_ID=$(az ad app create --display-name gh-diceus-claims-deploy --query appId -o tsv)
az ad sp show --id "$APP_ID" -o none 2>/dev/null || az ad sp create --id "$APP_ID" -o none
[ -n "$(az ad app federated-credential list --id "$APP_ID" --query "[?name=='github-main'].name" -o tsv)" ] || \
  az ad app federated-credential create --id "$APP_ID" -o none --parameters '{"name":"github-main","issuer":"https://token.actions.githubusercontent.com","subject":"repo:ponatosik/diceus-claims-module:ref:refs/heads/main","audiences":["api://AzureADTokenExchange"]}'
SP_ID=$(az ad sp show --id "$APP_ID" --query id -o tsv)
RG_ID=$(az group show --name rg-diceus-claims --query id -o tsv)
sleep 20  # let the new service principal propagate before assigning roles
assign() {  # role [condition]: idempotent, and loud on failure (set -e)
  if [ "$(az role assignment list --assignee "$SP_ID" --scope "$RG_ID" --role "$1" --query 'length(@)' -o tsv)" = "0" ]; then
    if [ -n "${2:-}" ]; then
      az role assignment create --assignee-object-id "$SP_ID" --assignee-principal-type ServicePrincipal --role "$1" --scope "$RG_ID" --condition "$2" --condition-version 2.0 -o none
    else
      az role assignment create --assignee-object-id "$SP_ID" --assignee-principal-type ServicePrincipal --role "$1" --scope "$RG_ID" -o none
    fi
  fi
  echo "  ✓ $1"
}
assign "Contributor"
assign "Key Vault Secrets Officer"   # provision.yml reuses existing secrets; deploy.yml reads the DB connection
# Least privilege: may only grant or remove "Key Vault Secrets User" (the API's managed identity role).
KV_SECRETS_USER=4633458b-17de-408a-b874-0445c86b69e6
assign "Role Based Access Control Administrator" "((!(ActionMatches{'Microsoft.Authorization/roleAssignments/write'})) OR (@Request[Microsoft.Authorization/roleAssignments:RoleDefinitionId] ForAnyOfAnyValues:GuidEquals {$KV_SECRETS_USER})) AND ((!(ActionMatches{'Microsoft.Authorization/roleAssignments/delete'})) OR (@Resource[Microsoft.Authorization/roleAssignments:RoleDefinitionId] ForAnyOfAnyValues:GuidEquals {$KV_SECRETS_USER}))"
echo; echo "AZURE_CLIENT_ID=$APP_ID"; echo "AZURE_TENANT_ID=$TENANT_ID"; echo "AZURE_SUBSCRIPTION_ID=$SUBSCRIPTION_ID"
CLOUDSHELL
printf '%s──────────────── copy to here ──────────────────%s\n\n' "$DIM" "$RESET"
note "It is safe to run again: every step checks what already exists."
warn "If the offer printed is 'AzureForStudents…', stop: the Azure SQL free offer isn't available on it."
pause "Press Enter once the three AZURE_… lines have printed."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "GitHub: tell the workflows how to sign in to Azure"
say "Copy the three values printed at the end of the Cloud Shell output."
note "These are identifiers, not secrets: GitHub signs in with OIDC, so no password is stored anywhere."
guid='^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
for name in AZURE_CLIENT_ID AZURE_TENANT_ID AZURE_SUBSCRIPTION_ID; do
  while true; do
    ask "$name" "Paste $name:"
    [[ "${!name}" =~ $guid ]] && break
    warn "That doesn't look like a GUID — paste just the value after '$name='."
  done
  GH_REPO="$REPO" set_var "$name" "${!name}"
done

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Budget alerts"
say "The \$2/month budget emails this address at 50% and 100% of actual spend, and at 100% of forecast."
ask BUDGET_ALERT_EMAIL "Email for budget alerts (Enter = ponatosik@gmail.com):" || true
BUDGET_ALERT_EMAIL="${BUDGET_ALERT_EMAIL:-ponatosik@gmail.com}"
GH_REPO="$REPO" set_var BUDGET_ALERT_EMAIL "$BUDGET_ALERT_EMAIL"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Provision and deploy"
say "Everything from here runs in GitHub Actions: Bicep provisioning, then build, migrations, deploy and a smoke test."
# Trigger a workflow and print the id of *that* run (not merely the latest one).
dispatch() {
  local workflow="$1"; shift
  local since run_id=""
  since=$(date -u +%Y-%m-%dT%H:%M:%SZ)
  gh workflow run "$workflow" --repo "$REPO" "$@" >/dev/null
  for _ in $(seq 1 30); do
    sleep 3
    run_id=$(gh run list --repo "$REPO" --workflow "$workflow" --event workflow_dispatch --limit 5 \
      --json databaseId,createdAt --jq "[.[] | select(.createdAt >= \"$since\")] | last | .databaseId // empty")
    [[ -n "$run_id" ]] && { echo "$run_id"; return 0; }
  done
  return 1
}

if confirm "Run 'Provision Azure' now and wait for it (about 5-10 minutes)?"; then
  run_id=$(dispatch provision.yml) || { warn "Couldn't find the provision run — check the Actions tab."; finish; return; }
  gh run watch "$run_id" --repo "$REPO" --exit-status || { warn "Provisioning failed — see: gh run view $run_id --repo $REPO --log-failed"; finish; return; }
  if confirm "Provisioning succeeded. Run 'Deploy' now, seeding the demo claims?"; then
    run_id=$(dispatch deploy.yml -f seedDemoClaims=true) || { warn "Couldn't find the deploy run — check the Actions tab."; finish; return; }
    gh run watch "$run_id" --repo "$REPO" --exit-status || warn "Deploy failed — see: gh run view $run_id --repo $REPO --log-failed"
  else
    SKIPPED+=("Deploy: gh workflow run deploy.yml --repo $REPO -f seedDemoClaims=true")
  fi
else
  SKIPPED+=("Provision: gh workflow run provision.yml --repo $REPO, then Deploy")
fi

finish
}

run_wizard "$@"; exit
